import type { Hooks, TableHeaderProps, TableInstance } from 'react-table';

/** Uses the table instance to manipulate and extend the table behavior */
function useInstance(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  instance: TableInstance<any>,
) {
  const { getHooks, disableSortBy } = instance;

  if (!disableSortBy) {
    // Add aria-sorted attributes to the header cells
    getHooks().getHeaderProps.push((props, { column }) => {
      if (!column.canSort) {
        return [props, {}];
      }

      if (column.isSorted) {
        return column.isSortedDesc
          ? ([
              props,
              { 'aria-sort': 'descending' },
            ] as Partial<TableHeaderProps>)
          : ([
              props,
              { 'aria-sort': 'ascending' },
            ] as Partial<TableHeaderProps>);
      }

      return [props, { 'aria-sort': 'none' }] as Partial<TableHeaderProps>;
    });
  }
}

/**
 * Hook for setting the proper aria-sort prop when a column gets sorted.
 */
export function useAriaSort(
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  hooks: Hooks<any>,
): void {
  hooks.useInstance.push(useInstance);
}

useAriaSort.pluginName = 'useAriaSort';
